/* @socom-skeleton body gridGetNextIndex__Q23zdb5CGridFv */
namespace zdb {
bool CGrid::gridGetNextIndex()
    {
        bool valid = false;

        if (m_PntCnt < 3)
        {
            if (m_zz < m_izb - 1)
            {
                valid = true;
                m_zz++;
            }
            else if (m_xx < m_ixb - 1)
            {
                valid = true;
                m_xx++;
                m_zz = m_iz;
                m_RowCellIn = 0;
            }
        }
        else
        {
            if (m_CurCellOut == 0 && m_zz < m_iz_next_row)
                m_iz_next_row = m_zz;

            if (m_iz_dir < 0)
            {
                if (m_CurCellOut == 0 && m_iz < m_zz)
                {
                    m_zz--;
                    return true;
                }

                m_zz = m_iz_start;
                m_iz_dir = 1;
                m_CurCellOut = 0;
            }

            if (m_RowCellIn == 0 || m_CurCellOut == 0 && m_zz < m_izb - 1)
            {
                valid = true;
                m_zz++;
            }
            else if (m_xx < m_ixb - 1)
            {
                m_xx++;

                if (m_iz_next_row == m_izb)
                {
                    m_zz = m_iz;
                    m_iz_dir = 1;
                }
                else
                {
                    m_zz = m_iz_next_row;

                    if (m_iz < m_zz)
                        m_zz++;

                    m_iz_dir = -1;
                }

                valid = true;
                m_iz_next_row = m_izb;
                m_iz_start = m_zz;
                m_RowCellIn = 0;
            }
            else
            {
                m_RowCellIn = 0;
                m_CurCellOut = 0;
                valid = false;
            }
        }

        return valid;
    }
}

/* @socom-skeleton stub gridGetGridXandZIndex__Q23zdb5CGridFPiPiff */
void zdb::CGrid::gridGetGridXandZIndex(int *x, int *z, float px, float pz)
{
	/* 0x215a30: VU0 vftoi0 (truncating) of the scaled offsets, clamped to the grid */
	s32 ix = (s32)(m_InvCellDim * (px - m_origin.x));
	s32 iz = (s32)(m_InvCellDim * (pz - m_origin.z));

	*x = ix < 0 ? 0 : ix;

	if (m_CellCount.cx <= *x)
		*x = m_CellCount.cx - 1;

	*z = iz < 0 ? 0 : iz;

	if (m_CellCount.cy <= *z)
		*z = m_CellCount.cy - 1;
}

